import {t,lang} from './i18n.js';
import {last,currentReview,currentResponse,currentOutcome,diagnosis,canVisit,CLINICIAN,GUIDELINE} from './care-model.js';
import {TrajectoryView} from './trajectory-view.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key={history:'historyNode',genome:'genomeNode',context:'contextNode',measurement:'todayNode',question:'questionNode',confirmation:'confirmationNode',discharge:'dischargeNode',signal:'signalNode',intervention:'interventionNode',response:'responseNode',outcome:'outcomeNode',learning_proposal:'learningNode'};
export class CareView{
 constructor(host,{dispatch,onReset,onBurst}){this.host=host;this.dispatch=dispatch;this.onReset=onReset;this.onBurst=onBurst;this.role='patient';this.selected=null;this.layer=false;this.trace=false;this.draft='';this.draftEdited=false;this.storage=true;this.paused=false;this.stage=null;}
 setPaused(v){this.paused=v;this.plot?.setPaused(v);}
 hide(){this.plot?.setActive(false);}
 show(state,storage=true){this.state=state;this.storage=storage;if(this.stage!==state.stage){this.stage=state.stage;this.role=['M1','M3'].includes(state.stage)?'clinician':'patient';this.selected=null;}this.render();}
 event(event){try{this.dispatch(event);this.onBurst?.();}catch(error){this.host.querySelector('#care-error').textContent=t(error.message==='QUESTION_REQUIRED'?'inputError':'error');}}
 visit(stage){this.event({type:'VISIT',stage});window.scrollTo({top:0,behavior:this.paused?'instant':'smooth'});}
 stamp(){const r=currentReview(this.state);return r?`<div class="confirmation-stamp"><span class="stamp-icon">✓</span><div><small>${t(diagnosis(this.state)?'confirmed':'deferred')}</small><strong>${t(diagnosis(this.state)?'diagnosis':'defer')}</strong><p>${t(diagnosis(this.state)?'relay':'deferRelay')}</p></div></div>`:'';}
 button(action,label,extra=''){return `<button class="care-primary" data-action="${action}" ${extra}>${t(label)} <span aria-hidden="true">↗</span></button>`;}
 next(text){return `<div class="step-label"><span class="live-dot"></span>${t('next')}</div><p class="step-context">${t(text)}</p>`;}
 question(){const q=last(this.state,'question');return q?`<blockquote class="question-record"><small>${t('questionNode')} · ${q.occurred_at.slice(5).replace('-','/')}</small><p>${esc(q.data.text)}</p><span>${t('original')} · ${esc(q.data.language.toUpperCase())}</span></blockquote>`:'';}
 panel(){const s=this.state,r=currentReview(s),response=currentResponse(s),outcome=currentOutcome(s),signal=last(s,'signal'),proposal=last(s,'intervention'),validProposal=proposal?.data.review===r?.id;
  if(s.stage==='W')return !last(s,'question')?`${this.next('questionNext')}<h3>${t('questionTitle')}</h3><form id="question-form"><label class="field-label" for="question-text">${t('questionLabel')}</label><textarea id="question-text" maxlength="600" rows="4" required>${esc(this.draftEdited?this.draft:t('questionDefault'))}</textarea><p class="fine">${t('questionHint')}</p>${this.button('save-question','saveQuestion','type="submit"')}</form><details class="guideline"><summary>${t('generalGuide')}</summary><p>${t('guideText')}</p><a href="${GUIDELINE}" target="_blank" rel="noopener">${t('guideSource')}</a></details>`:`${this.next('questionSavedDetail')}<h3>${t('questionSaved')}</h3>${this.question()}${this.stamp()}${this.button('to-doctor','toDoctor')}`;
  if(s.stage==='M1')return `${this.next('reviewNext')}${this.question()}${this.stamp()}${r?`<details class="review-revision"><summary>${t('reviewTitle')} ↗</summary>`:''}<h3>${t('reviewTitle')}</h3><p class="fine">${t('reviewHint')}</p><form id="review-form"><fieldset><legend>${t('decision')}</legend><label class="radio-line"><input type="radio" name="decision" value="confirm" ${!r||r.data.decision==='confirm'?'checked':''}>${t('confirm')}</label><label class="radio-line"><input type="radio" name="decision" value="defer" ${r?.data.decision==='defer'?'checked':''}>${t('defer')}</label></fieldset><label class="field-label" for="plan">${t('plan')}</label><select id="plan" name="plan"><option value="evening" ${r?.data.plan==='evening'?'selected':''}>${t('evening')}</option><option value="flexible" ${r?.data.plan==='flexible'?'selected':''}>${t('flexible')}</option></select>${this.button('confirm-review','confirmReview','type="submit"')}</form>${r?'</details>':''}${r?`<p class="fine">${t('reviewSaved')}</p>${this.button('to-aftercare','continueCare')}`:''}`;
  if(s.stage==='M3'){
   if(!signal&&this.role==='patient')return `${this.next('awaitReview')}<h3>${t('handoff')}</h3><p>${t('handoffBody')}</p>${this.button('doctor-view','viewReview')}`;
   if(!signal)return `${this.next('advanceNext')}<h3>${t('handoff')}</h3><p>${t('handoffBody')}</p>${this.stamp()}${this.button('advance','advance')}`;
   if(this.role==='clinician')return `${this.next('approveNext')}<h3>${t('signal')}</h3><p>${t('signalBody')}</p><p class="fine">${t('signalExplain')}</p><div class="evidence-block"><h4>${t('evidence')}</h4><ul><li>${t('evidence1')}</li><li>${t('evidence2')}</li><li>${t('evidence3')}</li></ul><small>${t('accountable')}</small><p>${t('doctor')}</p></div>${validProposal?`<div class="approved-line">✓ ${t('approved')}</div>${this.button('patient-view','showPatient')}`:`<form id="approve-form"><label class="check-line"><input id="evidence-reviewed" type="checkbox" required>${t('approveCheck')}</label>${this.button('approve','approve','type="submit"')}</form>`}`;
   if(!validProposal)return `${this.next('awaitReview')}<h3>${t('signal')}</h3><p>${t('signalBody')}</p>${this.button('doctor-view','viewReview')}`;
   if(!response)return `${this.next('responseNext')}<div class="message-node"><span class="message-origin">${t('approved')}</span><h3>${t('proposal')}</h3><p>${t('doctor')}</p><details><summary>${t('evidence')}</summary><ul><li>${t('evidence1')}</li><li>${t('evidence2')}</li><li>${t('evidence3')}</li></ul></details></div><div class="response-actions">${this.button('yes','yes')}<button class="care-secondary" data-action="no">${t('no')}</button></div>`;
   if(response.data.answer==='no')return `${this.next('returnNext')}<h3>${t('declined')}</h3><p>${t('declinedHint')}</p><div class="response-mark">↳ ${t('learningNode')}</div>${this.button('return','returnW')}`;
   return `${this.next(outcome?'returnNext':'observeNext')}<h3>${t(outcome?'observation':'accepted')}</h3><p>${t(outcome?'observed':'acceptedHint')}</p>${this.button(outcome?'return':'observe',outcome?'returnW':'observe')}`;
  }
  return `${this.next('inspectNext')}${this.stamp()}<h3>${t(outcome?'observation':response?.data.answer==='no'?'declined':'accepted')}</h3><p>${t(outcome?'observed':'notObserved')}</p>${response?.data.answer==='no'?`<p class="fine">${t('declinedHint')}</p>`:''}${this.question()}${this.button('explore','openLine')}`;
 }
 nodeBody(n){const s=this.state;switch(n.kind){case'question':return n.data.text;case'confirmation':return t(n.data.decision==='confirm'?'relay':'deferRelay');case'discharge':return t('handoffBody');case'signal':return t('signalBody');case'intervention':return t('proposal');case'response':return t(n.data.answer==='yes'?'acceptedHint':'declinedHint');case'outcome':return t('observed');case'learning_proposal':return t('learningBody');case'genome':return t('irisBody');case'context':return t('contextBody');case'history':return t('historyBody');default:return t('todayBody');}}
 render(){const s=this.state;this.plot?.destroy();const titleKey={W:'w',M1:'m1',M3:'m3',W2:'w2'}[s.stage];const stages=['W','M1','M3','W2'];const selected=s.nodes.find(n=>n.id===this.selected);const nodeButtons=s.nodes.map(n=>`<button class="record-chip ${this.selected===n.id?'selected':''}" data-node="${n.id}" aria-pressed="${this.selected===n.id}"><i class="node-dot ${n.kind==='confirmation'?'confirmed-dot':''}"></i><span>${t(key[n.kind])}</span></button>`).join('');
 this.host.innerHTML=`<div class="care-topline"><div><span class="care-patient">${t('patient')}</span><span class="case-caption">${t('fiction')}</span></div><span class="saved-state"><i></i>${t(this.storage?'saved':'memoryOnly')}</span></div><nav class="care-stages" aria-label="W M1 M3 W"><div class="stage-track"></div>${stages.map((stage,i)=>`<button data-visit="${stage}" class="${s.stage===stage?'active':''} ${canVisit(s,stage)?'available':''}" ${canVisit(s,stage)?'':'disabled'} ${s.stage===stage?'aria-current="step"':''}><span>${stage==='W2'?'W':stage}</span><strong>${t(['w','m1','m3','w2'][i])}</strong><i>${canVisit(s,stage)?'·':'⌁'}</i></button>`).join('')}</nav><div class="care-heading"><div><div class="eyebrow">ONE LIFE. ONE CONTINUOUS LINE.</div><h1>${t(titleKey+'Title')}</h1><p>${t(titleKey+'Desc')}</p></div><div class="role-area"><span>${t('roleDemo')}</span>${s.stage==='M3'?`<div class="role-switch"><button data-action="patient-view" class="${this.role==='patient'?'active':''}">${t('patientRole')}</button><button data-action="doctor-view" class="${this.role==='clinician'?'active':''}">${t('doctorRole')}</button></div>`:`<div class="role-indicator">${t(this.role==='clinician'?'doctorRole':'patientRole')}</div>`}</div></div><div class="care-layout"><section class="line-space" aria-label="${t('myLine')}"><div class="line-top"><span>${t('lineId')}</span><button class="layer-toggle" data-action="layer" aria-expanded="${this.layer}"><i>◈</i> ${t('iris')} <span>＋</span></button></div>${this.layer?`<div class="layer-detail"><strong>${t(this.role==='clinician'?'irisDoctor':'irisShort')}</strong><p>${t(this.role==='clinician'?'irisDoctorBody':'irisBody')}</p></div>`:''}<div class="trajectory-plot"><div class="plot-label sensitivity-label">${t('sensitivity')}</div><div class="plot-label baseline-label">${t('baseline')}</div><div class="future-label">${t('forecast')}<span>${t('uncertainty')}</span></div><div class="plot-node-layer">${s.nodes.map(n=>`<button data-plot-node="${n.id}" data-node="${n.id}" aria-label="${t(key[n.kind])}" title="${t(key[n.kind])}"></button>`).join('')}</div></div><div class="time-axis"><span>${t('past')}</span><span>${t('today')}</span><span>${t('future')}</span></div><p class="plot-note">${t('plotNote')}</p><div class="line-foundation"><i>◈</i><span>${t('irisShort')}</span><span class="goal-intention">${t('goal'+(Number(s.goal)||0))}</span></div><div class="record-rail">${nodeButtons}</div>${selected?`<article class="node-inspector"><div><span class="eyebrow">${t('record')} · ${selected.occurred_at}</span><button data-action="close-node" aria-label="${t('close')}">×</button></div><h3>${t(key[selected.kind])}</h3><p>${esc(this.nodeBody(selected))}</p>${selected.evidence_refs?.length?`<small>${t('evidenceLinks')} · ${selected.evidence_refs.map(id=>esc(id)).join(' → ')}</small>`:''}</article>`:''}<button class="trace-toggle" data-action="trace" aria-expanded="${this.trace}">${t(this.trace?'hideTrace':'fullTrace')} <span>↗</span></button>${this.trace?`<div class="trace"><p>${t('traceNotice')}</p>${s.audit.length?s.audit.map(log=>{const n=s.nodes.find(n=>n.id===log.node_id);return`<div class="trace-row"><time>${n.occurred_at}</time><span>${t(key[n.kind])}<small>${n.id} · ${log.actor===CLINICIAN?t('doctor'):esc(log.actor)}</small></span></div>`;}).join(''):`<p>${t('noTrace')}</p>`}</div>`:''}</section><aside class="care-action-panel" aria-live="polite">${this.panel()}<p id="care-error" class="care-error" role="alert"></p></aside></div><button class="mobile-next" data-action="next">${t('next')} <span aria-hidden="true">↗</span></button><div class="care-bottom"><span>${t('browserOnly')}</span><button data-action="reset">${t('resetCase')} ↺</button></div>`;
 this.plot=new TrajectoryView(this.host.querySelector('.trajectory-plot'));this.plot.update(s,this.selected);this.plot.setPaused(this.paused);
 this.host.querySelectorAll('[data-node]').forEach(b=>b.addEventListener('click',()=>{this.selected=this.selected===b.dataset.node?null:b.dataset.node;this.render();}));
 this.host.querySelectorAll('[data-visit]').forEach(b=>b.addEventListener('click',()=>this.visit(b.dataset.visit)));
 this.host.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{if(b.type!=='submit'||!b.closest('form'))this.action(b.dataset.action);}));
 const q=this.host.querySelector('#question-form');q?.addEventListener('submit',e=>{e.preventDefault();this.event({type:'QUESTION',role:'patient',text:this.host.querySelector('#question-text').value,language:this.draftEdited?this.draftLanguage:lang()});});this.host.querySelector('#question-text')?.addEventListener('input',e=>{this.draft=e.target.value;this.draftLanguage=lang();this.draftEdited=true;});
 this.host.querySelector('#review-form')?.addEventListener('submit',e=>{e.preventDefault();const values=new FormData(e.target);this.event({type:'REVIEW',role:this.role,decision:values.get('decision'),plan:values.get('plan')});});
 this.host.querySelector('#approve-form')?.addEventListener('submit',e=>{e.preventDefault();this.event({type:'APPROVE',role:this.role,clinician:CLINICIAN,evidenceReviewed:this.host.querySelector('#evidence-reviewed').checked});});
 }
 action(a){switch(a){case'next':this.host.querySelector('.care-action-panel').scrollIntoView({behavior:this.paused?'instant':'smooth',block:'start'});break;case'to-doctor':this.visit('M1');break;case'to-aftercare':this.visit('M3');break;case'return':this.visit('W2');break;case'advance':this.event({type:'ADVANCE',role:this.role});break;case'patient-view':this.role='patient';this.render();break;case'doctor-view':this.role='clinician';this.render();break;case'yes':case'no':this.event({type:'RESPOND',role:this.role,answer:a});break;case'observe':this.event({type:'OBSERVE',role:this.role});break;case'layer':this.layer=!this.layer;this.render();break;case'trace':this.trace=!this.trace;this.render();break;case'close-node':this.selected=null;this.render();break;case'explore':this.selected=currentReview(this.state)?.id||this.state.nodes[0].id;this.trace=true;this.render();break;case'reset':this.onReset();break;}}
}
